test_suite:
test('values start as empty strings', () => {
  const { result } = renderHook(() =>
    useFormValidation({ email: v => v ? null : 'Required' })
  );
  expect(result.current.values.email).toBe('');
});

test('handleChange updates a value', () => {
  const { result } = renderHook(() =>
    useFormValidation({ name: () => null })
  );
  act(() => result.current.handleChange('name', 'Alice'));
  expect(result.current.values.name).toBe('Alice');
});

test('error not shown before blur', () => {
  const { result } = renderHook(() =>
    useFormValidation({ email: v => v.includes('@') ? null : 'Invalid' })
  );
  expect(result.current.errors.email).toBeUndefined();
});

test('error shown after blur', () => {
  const { result } = renderHook(() =>
    useFormValidation({ email: v => v.includes('@') ? null : 'Invalid' })
  );
  act(() => result.current.handleBlur('email'));
  expect(result.current.errors.email).toBe('Invalid');
});

test('isValid false when errors exist', () => {
  const { result } = renderHook(() =>
    useFormValidation({ email: v => v ? null : 'Required' })
  );
  act(() => result.current.handleBlur('email'));
  expect(result.current.isValid).toBe(false);
});

// __hidden__
test('isValid true after all fields pass validation', () => {
  const { result } = renderHook(() =>
    useFormValidation({ email: v => v.includes('@') ? null : 'Invalid' })
  );
  act(() => result.current.handleChange('email', 'a@b.com'));
  act(() => result.current.handleBlur('email'));
  expect(result.current.isValid).toBe(true);
});

solution:
import { useState } from 'react';

type Rules = Record<string, (value: string) => string | null>;

export function useFormValidation(rules: Rules) {
  const initialValues = Object.fromEntries(Object.keys(rules).map(k => [k, '']));
  const [values, setValues] = useState<Record<string, string>>(initialValues);
  const [touched, setTouched] = useState<Record<string, boolean>>({});

  const handleChange = (field: string, value: string) =>
    setValues(v => ({ ...v, [field]: value }));

  const handleBlur = (field: string) =>
    setTouched(t => ({ ...t, [field]: true }));

  const errors: Record<string, string> = {};
  for (const [field, validate] of Object.entries(rules)) {
    if (touched[field]) {
      const error = validate(values[field] ?? '');
      if (error) errors[field] = error;
    }
  }

  const isValid = Object.entries(rules).every(([field, validate]) => !validate(values[field] ?? ''));

  return { values, errors, touched, handleChange, handleBlur, isValid };
}
